styles:
:root{--bg:#070707;--bg2:#0d0d0d;--paper:#f1eee7;--paper2:#e7e3dc;--ink:#0b0b0b;--text:#f5f2ec;--muted:#a7a39c;--line:rgba(255,255,255,.15);--line-dark:rgba(11,11,11,.15);--red:#e81848;--max:1480px;--pad:clamp(20px,3.35vw,58px);--ease:cubic-bezier(.16,1,.3,1);--font:"Helvetica Neue",Helvetica,Arial,sans-serif}
*{box-sizing:border-box}html{scroll-behavior:smooth;background:var(--bg)}body{margin:0;background:var(--bg);color:var(--text);font-family:var(--font);font-size:16px;line-height:1.5;overflow-x:hidden}body.menu-open{overflow:hidden}a{color:inherit;text-decoration:none}button,input,textarea,select{font:inherit}button{color:inherit}img{display:block;width:100%;height:auto}.shell{width:min(var(--max),100%);margin-inline:auto;padding-inline:var(--pad)}
.skip{position:fixed;left:12px;top:12px;z-index:200;background:var(--paper);color:var(--ink);padding:10px 14px;transform:translateY(-140%);transition:.2s}.skip:focus{transform:none}
.nav{height:82px;position:fixed;z-index:90;top:0;left:0;right:0;display:grid;grid-template-columns:auto 1fr auto;align-items:center;padding:0 var(--pad);background:rgba(7,7,7,.76);backdrop-filter:blur(16px);border-bottom:1px solid rgba(255,255,255,.08)}.brand{display:flex;align-items:center;gap:10px;font-weight:760;letter-spacing:-.045em;font-size:18px}.brand-dot{width:28px;height:28px;display:grid;place-items:center;position:relative}.brand-dot:before,.brand-dot:after{content:"";position:absolute;background:var(--red);transform:skewX(-28deg)}.brand-dot:before{width:8px;height:27px;left:6px}.brand-dot:after{width:18px;height:7px;right:2px;top:2px}.nav-links{justify-self:end;display:flex;align-items:center;gap:clamp(18px,2vw,34px);font-size:13px}.nav-links a{color:#d8d5d0;transition:color .2s}.nav-links a:hover,.nav-links a:focus-visible,.nav-links a[aria-current="page"]{color:#fff}.nav-cta{border:1px solid rgba(255,255,255,.26);padding:11px 16px;background:#fff;color:#0b0b0b!important}.menu-btn{display:none;width:46px;height:46px;background:none;border:1px solid rgba(255,255,255,.2);align-items:center;justify-content:center;cursor:pointer;position:relative}.menu-btn span,.menu-btn:before{content:"";display:block;width:18px;height:1px;background:currentColor;position:absolute}.menu-btn span{transform:translateY(4px)}.menu-btn:before{transform:translateY(-4px)}.mobile-menu{display:none;position:fixed;inset:82px 0 0;z-index:80;background:#070707;padding:32px var(--pad) 40px}.mobile-menu.open{display:block}.mobile-menu a{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding:18px 0;font-size:clamp(28px,7vw,42px);letter-spacing:-.04em}.mobile-menu a:last-child{color:var(--red)}
.kicker{font-size:11px;text-transform:uppercase;letter-spacing:.19em;color:var(--muted)}.btn{display:inline-flex;min-height:50px;align-items:center;justify-content:center;padding:13px 19px;border:1px solid rgba(255,255,255,.26);font-size:13px;transition:transform .25s var(--ease),background .25s,border-color .25s}.btn:hover{transform:translateY(-2px);border-color:#fff}.btn.primary{background:var(--red);border-color:var(--red);color:#fff}.text-link{display:inline-flex;gap:10px;align-items:center;padding:10px 0;border-bottom:1px solid currentColor;font-size:13px}.reveal{opacity:0;transform:translateY(24px);transition:opacity .72s var(--ease),transform .72s var(--ease)}.reveal.in{opacity:1;transform:none}
/* HERO */
.hero{min-height:100svh;padding-top:82px;display:grid;align-items:stretch;position:relative;overflow:hidden}.hero-grid{display:grid;grid-template-columns:1.05fr .95fr;min-height:calc(100svh - 82px)}.hero-copy{padding:clamp(72px,8vw,126px) var(--pad) 56px max(var(--pad),calc((100vw - var(--max))/2 + var(--pad)));display:flex;flex-direction:column;justify-content:space-between}.hero-top{display:flex;justify-content:space-between;gap:30px;border-bottom:1px solid var(--line);padding-bottom:18px}.hero-top span:last-child{font-size:11px;color:#b6b1aa}.hero h1{margin:clamp(44px,6vw,88px) 0 0;font-size:clamp(58px,7.2vw,116px);line-height:.87;letter-spacing:-.072em;font-weight:520;max-width:880px}.hero h1 em{font-style:normal;color:var(--red)}.hero-bottom{display:grid;grid-template-columns:1fr auto;gap:34px;align-items:end;margin-top:64px}.hero-lead{font-size:clamp(18px,1.3vw,22px);line-height:1.48;color:#ddd9d2;max-width:680px;margin:0}.hero-actions{display:flex;gap:10px;flex-wrap:wrap;justify-content:flex-end}.hero-media{position:relative;overflow:hidden;min-height:680px}.hero-media img{position:absolute;inset:-5%;width:110%;height:110%;object-fit:cover;object-position:50% 51%;filter:saturate(.88) contrast(1.03);transform:scale(var(--hero-scale,1.035)) translateY(var(--hero-y,0))}.hero-media:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.06),rgba(0,0,0,.06) 58%,rgba(0,0,0,.55))}.hero-stamp{position:absolute;left:28px;bottom:28px;z-index:3;display:flex;align-items:center;gap:13px;font-size:11px;text-transform:uppercase;letter-spacing:.13em}.hero-stamp:before{content:"";width:42px;height:2px;background:var(--red)}
/* CHOICE */
#analysen,#projekt{scroll-margin-top:92px}.choice{background:var(--paper);color:var(--ink);padding:clamp(110px,12vw,185px) 0}.choice-head{display:grid;grid-template-columns:.35fr 1.65fr;gap:clamp(30px,7vw,100px);align-items:start}.choice h2{font-size:clamp(54px,7.4vw,112px);line-height:.88;letter-spacing:-.07em;font-weight:530;margin:0;max-width:1100px}.choice h2 span{color:var(--red)}.choice-list{margin-top:clamp(70px,8vw,118px);border-top:1px solid var(--line-dark)}.choice-row{width:100%;border:0;border-bottom:1px solid var(--line-dark);background:transparent;color:var(--ink);display:grid;grid-template-columns:80px 1fr 1fr auto;gap:28px;align-items:center;text-align:left;padding:28px 0;cursor:pointer;transition:padding .35s var(--ease),background .35s}.choice-row:hover,.choice-row.active{padding-left:18px;padding-right:18px;background:rgba(11,11,11,.035)}.choice-row .num{font-size:12px;color:#77716b}.choice-row h3{font-size:clamp(28px,3.2vw,50px);font-weight:520;letter-spacing:-.055em;margin:0}.choice-row p{margin:0;color:#5c5751;max-width:520px}.choice-row .arrow{font-size:28px;transition:transform .3s var(--ease)}.choice-row:hover .arrow,.choice-row.active .arrow{transform:translate(5px,-5px)}
/* BRIEF */
.brief{background:#090909;padding:clamp(110px,11vw,170px) 0}.brief-grid{display:grid;grid-template-columns:.76fr 1.24fr;gap:clamp(44px,8vw,128px);align-items:start}.brief-intro{position:sticky;top:120px}.brief-intro h2{font-size:clamp(46px,5.7vw,86px);line-height:.92;letter-spacing:-.065em;font-weight:520;margin:18px 0 28px}.brief-intro p{font-size:18px;color:#bbb6af;max-width:540px;margin:0}.brief-index{margin-top:56px;display:flex;gap:11px}.brief-index span{width:38px;height:2px;background:rgba(255,255,255,.18)}.brief-index span.active{background:var(--red)}.form-card{background:var(--paper);color:var(--ink);padding:clamp(28px,4.2vw,62px);min-height:700px}.form-top{display:flex;justify-content:space-between;gap:24px;padding-bottom:24px;border-bottom:1px solid var(--line-dark);margin-bottom:40px}.form-top strong{font-size:13px}.form-top span{font-size:12px;color:#77716b}.field{margin-bottom:34px}.field label,.field legend{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.14em;margin-bottom:12px;color:#615c56}.field input,.field textarea{width:100%;border:0;border-bottom:1px solid #aaa49b;background:transparent;color:var(--ink);padding:12px 0 14px;font-size:clamp(20px,2vw,30px);letter-spacing:-.03em;outline:none}.field textarea{min-height:120px;resize:vertical}.field input:focus,.field textarea:focus{border-color:var(--red)}.service-picks{display:grid;grid-template-columns:1fr 1fr;gap:10px}.service-pick{border:1px solid #b8b2aa;background:transparent;padding:15px;text-align:left;cursor:pointer;transition:.2s}.service-pick:hover,.service-pick.active{background:#0c0c0c;color:#fff;border-color:#0c0c0c}.budget-picks{display:flex;flex-wrap:wrap;gap:8px}.budget-pick{border:1px solid #bbb5ad;background:transparent;padding:10px 13px;cursor:pointer}.budget-pick.active{background:var(--red);border-color:var(--red);color:#fff}.form-submit{display:flex;justify-content:space-between;gap:24px;align-items:center;margin-top:46px;padding-top:26px;border-top:1px solid var(--line-dark)}.form-submit p{font-size:12px;color:#77716b;max-width:390px;margin:0}.form-submit button{border:0;background:var(--red);color:white;padding:15px 20px;min-height:52px;cursor:pointer}.form-success{display:none;margin-top:24px;padding:17px 18px;background:#0b0b0b;color:#fff}.form-success.show{display:block}
/* ANALYSES */
.analyses{background:var(--paper2);color:var(--ink);padding:clamp(110px,11vw,170px) 0}.analyses-head{display:grid;grid-template-columns:.4fr 1.6fr;gap:70px;margin-bottom:70px}.analyses h2{margin:0;font-size:clamp(46px,5.8vw,88px);line-height:.92;letter-spacing:-.064em;font-weight:520;max-width:1000px}.analysis-grid{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--line-dark);border-left:1px solid var(--line-dark)}.analysis-card{min-height:360px;padding:26px;border-right:1px solid var(--line-dark);border-bottom:1px solid var(--line-dark);display:flex;flex-direction:column;justify-content:space-between;transition:background .3s var(--ease),color .3s}.analysis-card:hover{background:#0a0a0a;color:#fff}.analysis-card .num{font-size:12px;color:#77716b}.analysis-card:hover .num{color:#aaa}.analysis-card h3{font-size:clamp(24px,2.2vw,35px);letter-spacing:-.045em;font-weight:520;line-height:1.05;margin:26px 0 18px}.analysis-card p{margin:0;color:#59544e}.analysis-card:hover p{color:#c9c5be}.analysis-card a{margin-top:28px;font-size:13px;display:flex;justify-content:space-between;padding-top:16px;border-top:1px solid currentColor}
/* LOCATION */
.location{background:#070707;padding:clamp(110px,11vw,170px) 0}.location-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(44px,7vw,110px);align-items:center}.location-visual{aspect-ratio:1.32/1;overflow:hidden}.location-visual img{height:100%;object-fit:cover;object-position:50% 52%;filter:saturate(.82)}.location h2{font-size:clamp(50px,6vw,92px);line-height:.9;letter-spacing:-.068em;font-weight:520;margin:18px 0 30px}.location p{font-size:18px;color:#bbb6af;max-width:610px}.locations{display:flex;gap:8px;flex-wrap:wrap;margin-top:34px}.locations span{border:1px solid var(--line);padding:9px 12px;font-size:12px}
/* DIRECT */
.direct{background:var(--red);color:white;padding:clamp(90px,9vw,135px) 0}.direct-top{display:flex;justify-content:space-between;padding-bottom:20px;border-bottom:1px solid rgba(255,255,255,.35)}.direct h2{font-size:clamp(55px,7.5vw,116px);line-height:.86;letter-spacing:-.075em;font-weight:520;margin:48px 0 58px;max-width:1200px}.direct-row{display:grid;grid-template-columns:1fr repeat(3,auto);gap:24px;align-items:end}.direct-row p{max-width:650px;margin:0;font-size:18px}.direct-mode{border-bottom:1px solid rgba(255,255,255,.65);padding:12px 0;font-size:13px;white-space:nowrap}
.footer{background:#050505;padding:68px 0 28px}.footer-top{display:grid;grid-template-columns:1fr 1.2fr;gap:70px;padding-bottom:52px}.footer-brand{font-size:54px;letter-spacing:-.06em;font-weight:700}.footer-top p{color:#8f8a84;max-width:330px}.footer-map{display:grid;grid-template-columns:repeat(3,1fr);gap:32px}.footer-map strong{font-size:12px;text-transform:uppercase;letter-spacing:.13em;color:#77736e;margin-bottom:16px;display:block}.footer-map a,.footer-map span{display:block;font-size:14px;padding:4px 0;color:#c4c0ba}.footer-bottom{display:grid;grid-template-columns:1fr auto auto;gap:24px;border-top:1px solid var(--line);padding-top:24px;color:#77736e;font-size:11px}.footer-bottom div{display:flex;gap:20px}
@media(max-width:1050px){.nav-links{display:none}.menu-btn{display:flex}.hero-grid{grid-template-columns:1fr}.hero-copy{min-height:68svh;padding-left:var(--pad)}.hero-media{min-height:54svh}.choice-head,.analyses-head{grid-template-columns:1fr;gap:24px}.brief-grid{grid-template-columns:1fr}.brief-intro{position:relative;top:auto}.analysis-grid{grid-template-columns:1fr 1fr}.location-grid{grid-template-columns:1fr}.direct-row{grid-template-columns:1fr 1fr}.direct-row p{grid-column:1/-1;margin-bottom:18px}}
@media(max-width:700px){.nav{height:72px}.mobile-menu{inset:72px 0 0}.hero{padding-top:72px}.hero-grid{min-height:0}.hero-copy{min-height:auto;padding-top:60px;padding-bottom:44px}.hero-top span:last-child{display:none}.hero h1{font-size:clamp(52px,16vw,74px);margin-top:48px}.hero-bottom{grid-template-columns:1fr;margin-top:44px}.hero-actions{justify-content:flex-start}.hero-media{min-height:56svh}.choice{padding:92px 0}.choice-row{grid-template-columns:42px 1fr auto;gap:14px;padding:22px 0}.choice-row p{grid-column:2/-1}.choice-row h3{font-size:31px}.brief{padding:92px 0}.brief-intro h2{font-size:50px}.form-card{padding:24px;min-height:0}.service-picks{grid-template-columns:1fr}.form-submit{display:block}.form-submit button{width:100%;margin-top:20px}.analysis-grid{grid-template-columns:1fr}.analysis-card{min-height:300px}.location{padding:90px 0}.location h2{font-size:54px}.direct{padding:84px 0}.direct-top span:last-child{display:none}.direct h2{font-size:57px}.direct-row{grid-template-columns:1fr}.direct-mode{display:block}.footer-top{grid-template-columns:1fr}.footer-map{grid-template-columns:1fr 1fr}.footer-bottom{grid-template-columns:1fr;gap:12px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.reveal{opacity:1;transform:none;transition:none}.hero-media img{transform:none!important}.choice-row,.btn{transition:none}}

/* AROZ R2 – detail craft / accessibility; scoped additions only. */
html { scroll-padding-top: 90px; }
:where(h1,h2,h3) { text-wrap: balance; }
:where(p,li,dd) { overflow-wrap: break-word; }
:where(a, button, input, select, textarea):focus-visible { outline: 2px solid #ff4164; outline-offset: 4px; box-shadow: 0 0 0 2px rgba(0,0,0,.5); }
:where(button, input, textarea, select) { font: inherit; }
:where(img) { max-width:100%; }
@media(prefers-reduced-motion:reduce){ html{scroll-behavior:auto!important} *,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important} }
@media(max-width:620px){
 :where(h1,h2,h3) { hyphens:auto; overflow-wrap:normal; }
 :where(p) { line-height:1.55; }
 :where(a,button) { -webkit-tap-highlight-color:transparent; }
}

/* Typography AA craft floor for legacy 8-10px labels */



/* P0: form focus, error visibility and honest demo messaging. */
.form-card :where(input, textarea, select){min-height:45px}
.form-card :where(input, textarea, select):focus-visible{outline:2px solid #e81848;outline-offset:3px}
.form-success{line-height:1.55}
.form-submit p{max-width:54ch}
@media(max-width:620px){.form-card label{line-height:1.4}.form-submit button{min-height:50px}}

scripts.code:
(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const menuBtn=document.querySelector('.menu-btn'),menu=document.querySelector('.mobile-menu');if(menuBtn&&menu){menuBtn.addEventListener('click',()=>{const open=menuBtn.getAttribute('aria-expanded')==='true';menuBtn.setAttribute('aria-expanded',String(!open));menu.classList.toggle('open',!open);menu.setAttribute('aria-hidden',String(open));document.body.classList.toggle('menu-open',!open)});addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.classList.contains('open'))menuBtn.click()})}
if(!reduce){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.14,rootMargin:'0px 0px -7%'});document.querySelectorAll('.reveal').forEach(x=>io.observe(x));let ticking=false;function update(){const hero=document.querySelector('.hero');if(hero){const r=hero.getBoundingClientRect(),p=Math.max(0,Math.min(1,-r.top/innerHeight));hero.style.setProperty('--hero-scale',String(1.04-p*.025));hero.style.setProperty('--hero-y',`${p*18}px`)}ticking=false}addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(update);ticking=true}},{passive:true});update()}else document.querySelectorAll('.reveal').forEach(x=>x.classList.add('in'));
const serviceValue=document.querySelector('#serviceValue'),picks=[...document.querySelectorAll('.service-pick')],rows=[...document.querySelectorAll('.choice-row')];function choose(v){if(serviceValue)serviceValue.value=v;picks.forEach(x=>{const selected=x.dataset.value===v;x.classList.toggle('active',selected);x.setAttribute('aria-pressed',String(selected))});rows.forEach(x=>{const selected=x.dataset.service===v;x.classList.toggle('active',selected);x.setAttribute('aria-pressed',String(selected))})}picks.forEach(x=>x.addEventListener('click',()=>choose(x.dataset.value)));rows.forEach(x=>x.addEventListener('click',()=>{choose(x.dataset.service);document.querySelector('#projekt')?.scrollIntoView({behavior:reduce?'auto':'smooth'})}));document.querySelectorAll('.budget-pick').forEach(x=>x.addEventListener('click',()=>{document.querySelectorAll('.budget-pick').forEach(y=>y.classList.remove('active'));x.classList.add('active')}));document.querySelector('#contactForm')?.addEventListener('submit',e=>{e.preventDefault();(()=>{const status=document.querySelector('.form-success');if(status){status.classList.add('show');status.focus({preventScroll:true})}})()});})();
